  modelCalls: counter,
  inputTokens: counter,
  outputTokens: counter,
  reservedInputTokens: counter,
  reservedOutputTokens: counter,
  audioGenerations: counter,
  asrSeconds: seconds,
  providerRequests: z.array(receipt),
